/**
 * One cuộc trò chuyện, as the list draws it — deliberately without its
 * turns. The list is fifty rows in a panel about 20rem wide, and a payload
 * carrying every answer in every thread would be the learner's entire
 * history on every open, for a screen that shows three lines of each.
 */
export interface AssistantThread {
  id: string;
  /**
     * The first question asked in this thread, trimmed to 60 characters.
     * Never empty, and never written by a model: naming a conversation
     * would be a model call on the product's only per-learner variable
     * cost, and the learner has already typed a perfectly good label.
     */
  title: string;
  startedAt: string;
  /**
     * When the newest question in it landed. The list orders by this and
     * not by `startedAt` — a thread returned to after a week belongs at
     * the top, because that is what the learner just did with it.
     */
  lastAt: string;
  /**
     * How many questions are in it. One number rather than the turns
     * themselves; it is what tells a learner which of two similarly-named
     * threads is the one they spent an afternoon in.
     */
  turns: number;
}
